SELECT COUNT(DISTINCT ticket_id) AS recent_tickets
FROM support.tickets
WHERE opened_at > NOW() - INTERVAL '7 days';

SELECT COUNT(*) 
FROM support.tickets AS t 
WHERE t.priority = 'high' AND t.opened_at > NOW() - INTERVAL '1 DAY';

SELECT SUM(total_cost_usd) AS total_cost_usd
FROM marts.fct_outcomes
WHERE split = 'test' AND setup = 'B_local';

SELECT setup, accuracy 
FROM marts.mart_cost_per_outcome 
WHERE split = 'test';

SELECT marts.dim_tenant.monthly_budget_usd 
FROM marts.dim_tenant 
WHERE marts.dim_tenant.display_name = 'billing';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE cache_status = 'HIT';

SELECT COUNT(*) 
FROM marts.fct_outcomes 
WHERE prompt_version = 'none' AND split = 'tune';

SELECT COUNT(DISTINCT gold_label) AS distinct_gold_intents
FROM marts.fct_outcomes
WHERE split = 'test';

SELECT COUNT(*) 
FROM support.tickets t
WHERE t.tenant_id = 'support' AND t.status = 'open';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT COUNT(*) 
FROM support.ticket_events AS e 
WHERE e.event_type = 'reopened';

SELECT AVG(marts.agents.hourly_cost_usd) AS average_hourly_cost_usd
FROM marts.agents
WHERE marts.agents.is_active = TRUE;

SELECT COUNT(*)
FROM support.tickets t
WHERE t.assigned_agent_id IS NULL AND t.status = 'resolved';
